#include <iostream>

class Point {
    int x{0};
    int y{0};
    bool valid{false};

public:
    Point() = default;
    Point(int xVal, int yVal) : x(xVal), y(yVal), valid(true) {}

    friend std::istream& operator>>(std::istream& is, Point& p) {
        int tempX = 0;
        int tempY = 0;
        char ch1 = 0, ch2 = 0, ch3 = 0;

        // Expect format: (x,y)
        if (is >> ch1 >> tempX >> ch2 >> tempY >> ch3) {
            if (ch1 == '(' && ch2 == ',' && ch3 == ')') {
                p.x = tempX;
                p.y = tempY;
                p.valid = true;
                return is;
            }
        }
        is.setstate(std::ios_base::failbit);
        p.valid = false;
        return is;
    }

    friend std::ostream& operator<<(std::ostream& os, const Point& p) {
        if (!p.valid) {
            os << "[Invalid Point]";
        } else {
            os << "(" << p.x << ", " << p.y << ")";
        }
        return os;
    }
};

int main() {
    Point p1;
    if (std::cin >> p1) {
        std::cout << "Parsed p1: " << p1 << "\n";
    } else {
        std::cout << "Input error on p1\n";
        std::cin.clear();
    }

    Point p2;
    if (std::cin >> p2) {
        std::cout << "Parsed p2: " << p2 << "\n";
    } else {
        std::cout << "Input error on p2: " << p2 << "\n";
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

int main() {
    // Part 1: Radix formatting
    int sampleChar = 65; // 'A'
    std::cout << "Dec: " << std::dec << sampleChar
              << ", Oct: " << std::oct << sampleChar
              << ", Hex: " << std::hex << sampleChar
              << ", Char: " << static_cast<char>(sampleChar) << "\n";

    // Part 2: get vs getline delimiter behavior
    std::stringstream streamGet("Hello,World");
    char bufferGet[20];
    streamGet.get(bufferGet, 20, ',');
    char nextCharAfterGet = static_cast<char>(streamGet.peek());
    std::cout << "After get: read='" << bufferGet 
              << "', next in stream='" << nextCharAfterGet << "'\n";

    std::stringstream streamGetline("Hello,World");
    char bufferGetline[20];
    streamGetline.getline(bufferGetline, 20, ',');
    char nextCharAfterGetline = static_cast<char>(streamGetline.peek());
    std::cout << "After getline: read='" << bufferGetline 
              << "', next in stream='" << nextCharAfterGetline << "'\n";

    return 0;
}
